import datetime
import re
from decimal import Decimal
from typing import Dict, Iterator, List, Optional, Sequence, Tuple

from .models import Movement, Order, Product

SKU_RE = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
PRICE_RE = re.compile(r"[0-9]+(\.[0-9]{1,2})?")
REORDER_RE = re.compile(r"[0-9]+")
DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
SIGNED_QTY_RE = re.compile(r"[+-]?[0-9]+")
UNSIGNED_QTY_RE = re.compile(r"[0-9]+")
ORDER_ID_RE = re.compile(r"[Ss][Oo]-[0-9]+")
FIELD_SEP_RE = re.compile(r"[ \t]+")

TAX_RATES = {"standard": 20, "reduced": 5, "zero": 0}

# Python 3.11+ refuses int() on strings longer than 4300 digits; a whole number in a data file
# or on the command line may have at most this many significant digits on every Python version.
MAX_DIGITS = 4300


class ParseError(ValueError):
    """A mistake in a data file. ``.line`` is the 1-based line number."""

    def __init__(self, line: int, message: str):
        self.line = line
        self.reason = message
        super().__init__("line %d: %s" % (line, message))


def iter_data_lines(text: str) -> Iterator[Tuple[int, str]]:
    """Yield ``(line_number, line)`` for every non-blank, non-comment line.

    Lines end at LF or CRLF only; a lone CR stays inside the line.
    """
    if text.startswith("﻿"):
        text = text[1:]
    for number, line in enumerate(text.split("\n"), start=1):
        if line.endswith("\r"):
            line = line[:-1]
        if line.strip() == "" or line.lstrip().startswith("#"):
            continue
        yield number, line


def parse_date(value: str) -> Optional[datetime.date]:
    """Return the date for a ``YYYY-MM-DD`` string, or None if it is not a real date."""
    if not DATE_RE.fullmatch(value):
        return None
    try:
        return datetime.date(int(value[0:4]), int(value[5:7]), int(value[8:10]))
    except ValueError:
        return None


def valid_sku(value: str) -> bool:
    return SKU_RE.fullmatch(value) is not None


def valid_order_id(value: str) -> bool:
    return ORDER_ID_RE.fullmatch(value) is not None


def whole_number(text: str) -> Optional[int]:
    """Return the value of an optionally signed digit string, or None if it is too long.

    ``text`` must already match ``[+-]?[0-9]+``. Leading zeros do not count towards
    ``MAX_DIGITS``, so this never raises, whatever the length.
    """
    sign = -1 if text.startswith("-") else 1
    digits = text.lstrip("+-").lstrip("0") or "0"
    if len(digits) > MAX_DIGITS:
        return None
    return sign * int(digits)


def order_number(order_id: str) -> int:
    return int(order_id.split("-", 1)[1])


def order_number_key(order_id: str) -> Tuple[int, str]:
    """Sort key ordering ids by their number part numerically; any length, never raises."""
    digits = order_id.split("-", 1)[1].lstrip("0") or "0"
    return (len(digits), digits)


def _split_fields(line: str, maxsplit: int = 0) -> List[str]:
    stripped = line.strip(" \t")
    return FIELD_SEP_RE.split(stripped, maxsplit=maxsplit)


def parse_catalog(text: str) -> Dict[str, Product]:
    """Parse catalog.txt text into a dict of upper-case SKU -> Product."""
    catalog: Dict[str, Product] = {}
    for number, line in iter_data_lines(text):
        fields = [field.strip() for field in line.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(number, "expected 4 or 5 fields separated by '|', found %d" % len(fields))
        sku, name, price, reorder = fields[:4]
        if not valid_sku(sku):
            raise ParseError(number, "bad SKU %r" % sku)
        sku = sku.upper()
        if sku in catalog:
            raise ParseError(number, "duplicate SKU %s" % sku)
        if name == "":
            raise ParseError(number, "empty name")
        if not PRICE_RE.fullmatch(price) or Decimal(price) < Decimal("0.01"):
            raise ParseError(number, "bad price %r" % price)
        reorder_level = whole_number(reorder) if REORDER_RE.fullmatch(reorder) else None
        if reorder_level is None:
            raise ParseError(number, "bad reorder level %r" % reorder)
        tax = "standard"
        if len(fields) == 5:
            tax = fields[4].lower()
            if tax not in TAX_RATES:
                raise ParseError(number, "bad tax %r" % fields[4])
        catalog[sku] = Product(
            sku=sku,
            name=name,
            price=Decimal(price).quantize(Decimal("0.01")),
            reorder=reorder_level,
            tax=tax,
        )
    return catalog


