    """Indices of ``movements`` in the order they count: by date, same day in file order."""
    return sorted(range(len(movements)), key=lambda i: movements[i].date)


def first_negative(movements: Sequence[Movement]) -> Optional[int]:
    """Index of the first movement (in counting order) that takes a stock below zero."""
    balances: Dict[str, int] = {}
    for index in counting_order(movements):
        movement = movements[index]
        balance = balances.get(movement.sku, 0) + movement.quantity
        if balance < 0:
            return index
        balances[movement.sku] = balance
    return None


